(()=>{
const reciter=document.getElementById('reciter'),surah=document.getElementById('surah'),audio=document.getElementById('quran-audio'),continuous=document.getElementById('continuous'),status=document.getElementById('audio-status');let saved={};try{saved=JSON.parse(localStorage.getItem('adhan-audio')||'{}')}catch{}
for(const r of quranCatalog.reciters){const o=document.createElement('option');o.value=r.id;o.textContent=r.name;reciter.append(o)}
for(const s of quranCatalog.surahs){const o=document.createElement('option');o.value=String(s.id);o.textContent=`${s.id}. ${s.name}`;surah.append(o)}
reciter.value=quranCatalog.reciters.some(r=>r.id===saved.reciter)?saved.reciter:'123';surah.value=String(quranCatalog.surahs.some(s=>s.id===Number(saved.surah))?saved.surah:1);continuous.checked=saved.continuous!==false;
function persist(){try{localStorage.setItem('adhan-audio',JSON.stringify({reciter:reciter.value,surah:surah.value,continuous:continuous.checked}))}catch{}}
function mediaMetadata(r,s){if('mediaSession'in navigator&&typeof MediaMetadata!=='undefined'){navigator.mediaSession.metadata=new MediaMetadata({title:`${s.id}. ${s.name}`,artist:r.name,album:'The Holy Quran · Adhan'})}}
async function play(){try{await audio.play()}catch(e){status.textContent=e.name==='NotAllowedError'?'Tap Play in the audio player to continue.':'Unable to start audio. Check your connection and try Play again.'}}
function select(autoplay=false){const r=quranCatalog.reciters.find(r=>r.id===reciter.value),s=quranCatalog.surahs.find(s=>s.id===Number(surah.value));audio.pause();audio.src=`${r.server.replace(/\/$/,'')}/${String(s.id).padStart(3,'0')}.mp3`;audio.load();document.getElementById('track-title').textContent=s.name;document.getElementById('track-reciter').textContent=r.name;document.getElementById('previous-surah').disabled=s.id===1;document.getElementById('next-surah').disabled=s.id===114;status.textContent='Press Play to begin. Audio requires an internet connection.';mediaMetadata(r,s);persist();if(autoplay)play()}
function step(delta,autoplay=!audio.paused){const next=Number(surah.value)+delta;if(next<1||next>114)return;surah.value=String(next);select(autoplay)}
reciter.onchange=()=>select(!audio.paused);surah.onchange=()=>select(!audio.paused);continuous.onchange=persist;document.getElementById('previous-surah').onclick=()=>step(-1);document.getElementById('next-surah').onclick=()=>step(1);
audio.addEventListener('playing',()=>{status.textContent='Now playing · '+document.getElementById('track-title').textContent});audio.addEventListener('pause',()=>{if(!audio.ended&&!audio.error)status.textContent='Paused · Press Play to resume.'});audio.addEventListener('waiting',()=>{status.textContent='Buffering recitation…'});audio.addEventListener('error',()=>{status.textContent='This recording could not load. Check your internet connection or choose another reciter.'});audio.addEventListener('ended',()=>{if(continuous.checked&&Number(surah.value)<114)step(1,true);else status.textContent='Recitation complete.'});
if('mediaSession'in navigator){try{navigator.mediaSession.setActionHandler('play',play);navigator.mediaSession.setActionHandler('pause',()=>audio.pause());navigator.mediaSession.setActionHandler('previoustrack',()=>step(-1));navigator.mediaSession.setActionHandler('nexttrack',()=>step(1))}catch{}}
select();
})();
